window.MAGE_REMASTER=(()=>{
const data=window.MAGE_REMASTER_DATA,images=new Map(),previews=new Map(),framesCache=new Map();
const skins={mage:['default','blonde','elder','elf','demon'],warrior:['warrior-basic','warrior-female','warrior-elder','warrior-elf','warrior-demon'],rogue:['rogue-basic','rogue-female','rogue-shadow','rogue-desert','rogue-mask'],summoner:['summoner-beast','summoner-fairy','summoner-golem','summoner-skeleton','summoner-dragon']};
function sheet(key){if(images.has(key))return images.get(key);const rec={status:'loading',image:null};images.set(key,rec);if(typeof Image==='undefined'){rec.status='error';return rec;}const im=new Image();rec.image=im;im.onload=()=>{rec.status=im.naturalWidth?'ready':'error';window.dispatchEvent(new CustomEvent('mage-art-ready'));};im.onerror=()=>{rec.status='error';};im.src=window.MAGE_REMASTER_EMBEDDED?.[key]||data[key].path;return rec;}
function row(job,id){return Math.max(0,skins[job].indexOf(id));}
function motion(job,family,progress,casting,recovering,idleTime,lowFX){if(lowFX)return{key:job==='rogue'?(family==='fire'?'rogue-bow':'rogue-dagger'):job==='summoner'?'summoner-idle':job,frame:0};if(job==='warrior')return{key:job,frame:casting?Math.min(1,Math.floor(progress*2)):recovering?2:0};if(job==='summoner'&&!casting&&!recovering)return{key:'summoner-idle',frame:Math.floor(idleTime*2)%4};return{key:job==='rogue'?(family==='fire'?'rogue-bow':'rogue-dagger'):job==='summoner'?'summoner-cast':job,frame:casting?Math.min(2,Math.floor(progress*3)):recovering?3:0};}
function frameSheet(key,r,f){const rec=sheet(key);if(rec.status!=='ready')return null;const id=key+':'+r+':'+f;if(framesCache.has(id))return framesCache.get(id);const fr=data[key].frames[r]?.[f];if(!fr)return null;const pad=32,c=document.createElement('canvas');c.width=fr.sw+pad*2;c.height=fr.sh+pad*2;const cc=c.getContext('2d');cc.save();cc.beginPath();for(const run of fr.mask)for(let j=1;j<run.length;j+=2)cc.rect(pad+run[j],pad+run[0],run[j+1]-run[j],1);cc.clip();cc.drawImage(rec.image,fr.sx,fr.sy,fr.sw,fr.sh,pad,pad,fr.sw,fr.sh);cc.restore();const result={image:c,ax:fr.ax+pad,ay:fr.ay+pad,fr};framesCache.set(id,result);return result;}
function draw(ctx,key,r,f,x,feetY,height,maxWidth=220){const frame=frameSheet(key,r,f);if(!frame)return false;const ref=data[key].frames[r][0],scale=Math.min(height/ref.scaleHeight,maxWidth/ref.scaleWidth);ctx.drawImage(frame.image,x-frame.ax*scale,feetY-frame.ay*scale,frame.image.width*scale,frame.image.height*scale);return true;}
function hero(ctx,{job,id,family,progress,casting,recovering,time,x,y,lowFX,clone}){const m=motion(job,family,progress,casting,recovering,time,lowFX),r=row(job,id),height=job==='summoner'?180:job==='rogue'?145:160;if(clone){const source=frameSheet(m.key,r,m.frame);if(source){const cache='clone:'+m.key+':'+r+':'+m.frame;let spirit=framesCache.get(cache);if(!spirit){const c=document.createElement('canvas');c.width=source.image.width;c.height=source.image.height;const cc=c.getContext('2d');cc.drawImage(source.image,0,0);cc.globalCompositeOperation='source-in';cc.fillStyle='#aa87ff';cc.fillRect(0,0,c.width,c.height);spirit=c;framesCache.set(cache,spirit);}const ref=data[m.key].frames[r][0],scale=Math.min(height/ref.scaleHeight,220/ref.scaleWidth),cx=x+90,cy=y-20,dx=cx-source.ax*scale,dy=cy-source.ay*scale,w=spirit.width*scale,h=spirit.height*scale;ctx.save();ctx.globalAlpha*=.85;for(const [ox,oy] of [[-2,0],[2,0],[0,-2],[0,2]])ctx.drawImage(spirit,dx+ox,dy+oy,w,h);ctx.globalAlpha*=.8;ctx.drawImage(source.image,dx,dy,w,h);ctx.globalAlpha*=.55;ctx.drawImage(spirit,dx,dy,w,h);ctx.restore();}}return draw(ctx,m.key,r,m.frame,x,y,height);}
function enemy(ctx,type,size){return type>=6?draw(ctx,'enemies-extra',Math.floor((type-6)/2),(type-6)%2,0,2,size*2.2,size*3.5):draw(ctx,'enemies',Math.floor(type/3),type%3,0,2,size*2.2,size*3.5);}
function preview(job,id){const key=job==='rogue'?'rogue-dagger':job==='summoner'?'summoner-idle':job,r=row(job,id),cache=job+':'+id;if(previews.has(cache))return previews.get(cache);const frame=frameSheet(key,r,0);if(!frame)return null;const c=document.createElement('canvas');c.width=280;c.height=260;const cc=c.getContext('2d'),scale=Math.min(250/frame.image.width,235/frame.image.height),w=frame.image.width*scale,h=frame.image.height*scale;cc.drawImage(frame.image,(280-w)/2,(260-h)/2,w,h);const url=c.toDataURL('image/png');previews.set(cache,url);return url;}

function ally(ctx,a,time){const ids=['boar','wolf','griffin','spirit','greaterSpirit','spiritKing','skeleton','skeletonMage','deathKnight','golem','ironGolem','diamondGolem','dragon','ancientDragon'];const i=ids.indexOf(a.skill);if(i<0)return false;const air=['griffin','spirit','greaterSpirit','spiritKing','dragon','ancientDragon'].includes(a.skill),moving=a.skill==='boar'||!!a.n.speed;const bob=air?Math.sin(time*3+a.wave)*3:moving?Math.sin(time*10+a.wave)*1.5:0;const height=a.golem?96:a.skill==='ancientDragon'?125:a.skill==='dragon'?100:a.skill==='deathKnight'?80:a.skill.startsWith('skeleton')?55:65;const feet=a.y+26+bob;ctx.save();if(time<(a.flash||0))ctx.globalAlpha=.65;const ready=draw(ctx,'allies',Math.floor(i/4),i%4,a.x,feet,height,height*1.65);ctx.restore();if(ready&&a.n.hp){ctx.fillStyle='#39544e';ctx.fillRect(a.x-22,a.y+34,44,3);ctx.fillStyle='#9fecbd';ctx.fillRect(a.x-22,a.y+34,44*Math.max(0,a.hp/a.maxHP),3);}return ready;}
return{ally,hero,enemy,preview,motion,row,draw,sheet,frameSheet,data,images};})();
